function tdays(y,m,d){ return (new Date(y,m-1,d) - new Date(2026,9,26))/86400000/365.25 }

// A counter cashflows parametrized by note rate r, term n
function aCounter(r, n, disc){
  const ta = tdays(2028,1,5);
  const ORD=0.37, LTCG=0.20;
  const price=3_150_000, AR=200_000;
  const immOrd = 10_000 + 410_000, defOrd=0, defCap=350_000+2_000_000;
  const rD = (defOrd+defCap)/price;
  const pay = 2_850_000/n;
  let cf=[[300_000,ta],[AR,ta]];
  const d0=0, c0=rD*300_000;
  cf.push([-(immOrd*ORD+AR*ORD+c0*LTCG),ta]);
  let bal=2_850_000, interest=0;
  for(let k=1;k<=n;k++){const i=bal*r; interest+=i; bal-=pay; const t=ta+k;
    cf.push([pay+i,t]); cf.push([-(rD*pay*LTCG+i*ORD),t]);}
  const pv=x=>x.reduce((s,[a,t])=>s+a/(1+disc)**t,0);
  const nom=x=>x.reduce((s,[a])=>s+a,0);
  return {pv:pv(cf), nominal:nom(cf), interest};
}
// B: close year parameter, double vs single level
function buyerB(closeT, doubleLevel, disc, escrowFull=true){
  const tb=tdays(closeT,12,1);
  const ORD=0.37,LTCG=0.20,ENT=0.21;
  const O=420_000, C=2_010_000, nrg=1_140_000, entity=nrg*ENT;
  const ratio=500_000/2_850_000, C_close=C*(1-ratio), C_note=C*ratio;
  const cov_o=Math.min(O,nrg), cov_c=nrg-cov_o;
  const sh0=(O-cov_o)*ORD+Math.max(0,C_close-cov_c)*LTCG;
  const shNote=Math.max(0,C_note-Math.max(0,cov_c-C_close))*LTCG;
  const shTax = doubleLevel ? (O*ORD + C*LTCG) : (sh0+shNote);
  const tax = doubleLevel ? (entity + O*ORD + C*LTCG) : (entity + sh0 + shNote);
  const cf=[[2_350_000,tb],[escrowFull?100_000:0,tb+1],[-(entity+sh0),tb+0.5]];
  let bal=500_000;
  for(let k=1;k<=5;k++){const i=bal*0.06; bal-=100_000;
    cf.push([100_000+i,tb+k]); cf.push([-(shTax/5+i*ORD),tb+k]);}
  const pv=x=>x.reduce((s,[a,t])=>s+a/(1+disc)**t,0);
  const nom=x=>x.reduce((s,[a])=>s+a,0);
  return {pv:pv(cf), nominal:nom(cf), tax};
}
const rows=[];
for(const disc of [0.04,0.05,0.06,0.08]){
  const a5=aCounter(0.05,10,disc), a6=aCounter(0.06,10,disc), a6_7=aCounter(0.06,7,disc), b=buyerB(2026,false,disc);
  rows.push({disc, a5:Math.round(a5.pv), a6:Math.round(a6.pv), a6_7:Math.round(a6_7.pv), B:Math.round(b.pv)});
}
rows.forEach(r=>print(r));
print("nominals:", aCounter(0.05,10,0.06).nominal, aCounter(0.06,10,0.06).nominal, aCounter(0.06,7,0.06).nominal, buyerB(2026,false,0.06).nominal);
print("interest totals:", aCounter(0.05,10,.06).interest, aCounter(0.06,10,.06).interest, aCounter(0.06,7,.06).interest);
print("B 2028 close (outside period):");
// outside period: entity 0, full shareholder rates
{
  const disc=0.06, tb=tdays(2028,1,5);
  const O=420_000,C=2_010_000, ratio=500_000/2_850_000;
  const tax=O*0.37+C*0.20;
  const cf=[[2_350_000,tb],[100_000,tb+1],[-(O*0.37+C*(1-ratio)*0.20),tb+0.5]];
  let bal=500_000; const shNote=C*ratio*0.20;
  for(let k=1;k<=5;k++){const i=bal*0.06; bal-=100_000; cf.push([100_000+i,tb+k]); cf.push([-(shNote/5+i*0.37),tb+k]);}
  const pv=x=>x.reduce((s,[a,t])=>s+a/(1+disc)**t,0);
  print({tax, pv:Math.round(pv(cf))});
}
print("B escrow worst case (claims 285k): nominal impact", -285000);
print("B double-level total tax:", buyerB(2026,true,0.06).tax);

