  const shNote=Math.max(0,C_note-Math.max(0,cov_c-C_close))*LTCG;
  const tax = entity + sh0 + shNote;
  const cf=[[2_350_000,tb],[100_000,tb+1],[-(entity+sh0),tb+0.5]];
  let bal=500_000;
  for(let k=1;k<=5;k++){const i=bal*0.06; bal-=100_000;
    cf.push([100_000+i,tb+k]); cf.push([-(shNote/5+i*ORD),tb+k]);}
  const pv=x=>x.reduce((s,[a,t])=>s+a/(1+disc)**t,0);
  const nom=x=>x.reduce((s,[a])=>s+a,0);
  return {pv:pv(cf), nominal:nom(cf), tax};
}
